import { Image, PixelRatio, StyleSheet, type ImageStyle, type StyleProp } from 'react-native';
import { BRAND_NAME } from '../theme/brand';

/**
 * The one logo of the app. Nothing else loads a brand image: the bottom bar's create circle, the
 * header, the drawer and the login screen all come through this component.
 *
 * The pictures are generated by `tools/brand/make-assets.mjs` from
 * `assets-src/jungle-book-logo.jpg`; the field colour behind the letters is sampled from that
 * photograph, not invented here.
 *
 * - `header` is the 36 dp mark of the top bar, exported at 1x/2x/3x;
 * - `circle` is the masked round mark of the create button and the drawer;
 * - `large` is the full drawing of the login screen and of empty states.
 */
export type BrandLogoVariant = 'header' | 'circle' | 'large';

const headerSources = [
  require('../../assets/brand/jb-logo-header-1x.png'),
  require('../../assets/brand/jb-logo-header-2x.png'),
  require('../../assets/brand/jb-logo-header-3x.png'),
];
const circleSource = require('../../assets/brand/jb-logo-circle-256.png');
const largeSource = require('../../assets/brand/jb-logo-1024.png');

const defaultSizes: Record<BrandLogoVariant, number> = { header: 36, circle: 40, large: 132 };

/** The 3x header file is the sharpest one the generator writes. */
function headerSource(): number {
  const scale = Math.max(1, Math.min(3, Math.round(PixelRatio.get())));
  return headerSources[scale - 1];
}

export function BrandLogo({ variant = 'header', size, style, label }: {
  variant?: BrandLogoVariant;
  size?: number;
  style?: StyleProp<ImageStyle>;
  /** Only pass a label where the mark is not already read as part of a labelled button. */
  label?: string;
}) {
  const dimension = size ?? defaultSizes[variant];
  const source = variant === 'large' ? largeSource : variant === 'circle' ? circleSource : headerSource();
  return (
    <Image
      source={source}
      accessibilityRole={label ? 'image' : undefined}
      accessibilityLabel={label}
      accessible={Boolean(label)}
      accessibilityIgnoresInvertColors
      style={[
        { width: dimension, height: dimension },
        variant === 'circle' ? styles.circle : styles.square,
        style,
      ]}
    />
  );
}

const styles = StyleSheet.create({
  square: { borderRadius: 8 },
  circle: { borderRadius: 999 },
});

export const BRAND_LOGO_LABEL = `${BRAND_NAME} logo`;
